<template>
  <div class="liuyao-page page-transition"><section class="liuyao-card glass-card"><header><span>THE SIX LINES</span><h2>六爻算卦</h2><p>以当下心念起卦；结果用于自省与决策参考。</p></header>
    <div class="method-tabs"><button v-for="item in methods" :key="item.key" :class="{active: method === item.key}" @click="method = item.key"><b>{{ item.name }}</b><small>{{ item.hint }}</small></button></div>
    <textarea v-model="question" class="question" placeholder="写下你想问的事，起卦后可获取 AI 解读" maxlength="100"></textarea>
    <div v-if="method === 'numbers'" class="number-inputs"><input v-model.number="numbers[0]" type="number" placeholder="第一个数字"><input v-model.number="numbers[1]" type="number" placeholder="第二个数字"></div>
    <div class="btn-center"><button class="cast-btn" :disabled="loading" @click="cast">{{ loading ? '正在起卦…' : method === 'coins' ? '摇动三枚铜钱' : '开始起卦' }}</button></div>
    <div v-if="result" class="result"><div class="result-head"><div><small>本卦</small><h3>{{ result.original.name }}</h3><p>{{ result.original.upper.symbol }} {{ result.original.upper.name }}上 · {{ result.original.lower.symbol }} {{ result.original.lower.name }}下</p></div><div v-if="result.changed"><small>变卦</small><h3>{{ result.changed.name }}</h3><p>{{ result.changed.upper.symbol }} {{ result.changed.upper.name }}上 · {{ result.changed.lower.symbol }} {{ result.changed.lower.name }}下</p></div></div><p class="summary">{{ result.summary }}</p><div class="hexagrams"><section><b>本卦 · 自上而下</b><div v-for="line in reversedLines" :key="line.index" class="yao" :class="{moving: line.moving}"><span>第{{ line.index }}爻</span><i :class="{yang: line.yang}"></i><em v-if="line.moving">动</em></div></section><section v-if="result.changed"><b>变卦 · 动爻已变</b><div v-for="line in changedLines" :key="line.index" class="yao"><span>第{{ line.index }}爻</span><i :class="{yang: line.yang}"></i></div></section></div><div class="btn-center"><button class="cast-btn" :disabled="interpreting" @click="interpret">{{ interpreting ? '解读中…' : 'AI 解读此卦' }}</button></div><p v-if="interpretation" class="ai-result">{{ interpretation }}</p><footer>起卦时间：{{ new Date(result.createdAt).toLocaleString() }} · {{ methodName }}</footer></div>
  </section><Transition name="toast-fade"><div v-if="error" class="toast">{{ error }}</div></Transition></div>
</template>
<script setup lang="ts">
import { computed, ref } from "vue"
import { castLiuYao, interpretLiuYao, type LiuYaoResult } from "@/api"
const methods = [{key:"coins",name:"铜钱起卦",hint:"模拟三枚铜钱，逐爻摇卦"},{key:"numbers",name:"数字起卦",hint:"输入两个心中浮现的数字"},{key:"time",name:"时间起卦",hint:"以此刻时间起念"}] as const
const method = ref<typeof methods[number]["key"]>("coins"), numbers = ref<number[]>([]), question = ref(""), loading = ref(false), interpreting = ref(false), interpretation = ref(""), result = ref<LiuYaoResult | null>(null), error = ref("")
const reversedLines = computed(() => result.value ? [...result.value.lines].reverse() : []), changedLines = computed(() => result.value ? [...result.value.lines].map(line => ({...line, yang: line.moving ? !line.yang : line.yang})).reverse() : []), methodName = computed(() => methods.find(item => item.key === method.value)?.name)
async function cast(){if(method.value === "numbers" && (!Number.isInteger(numbers.value[0]) || !Number.isInteger(numbers.value[1]))){error.value="请输入两个整数后再起卦";return} loading.value=true;error.value="";try{result.value=await castLiuYao(method.value,numbers.value)}catch(e){error.value=e instanceof Error?e.message:"起卦失败"}finally{loading.value=false}}
async function interpret(){if(!result.value||!question.value.trim()){error.value="请填写问题后再请求 AI 解读";return}interpreting.value=true;try{interpretation.value=await interpretLiuYao(question.value,result.value)}catch(e){error.value=e instanceof Error?e.message:"解读失败"}finally{interpreting.value=false}}
</script>
<style scoped>
