ine-height:1.7}.ai-result{white-space:pre-wrap;text-align:left;background:rgba(255,255,255,.04);padding:16px;border-radius:8px}.hexagrams{display:flex;justify-content:center;gap:60px;margin:20px}.hexagrams section{width:260px}.hexagrams section>b{display:block;text-align:center;color:#d9bd79;font-size:12px;margin-bottom:12px}.yao{display:flex;align-items:center;gap:10px;height:32px}.yao span{width:42px;color:var(--text-dim);font-size:10px}.yao i{height:5px;flex:1;background:linear-gradient(90deg,#d4b26b 0 43%,transparent 43% 57%,#d4b26b 57%)}.yao i.yang{background:#d4b26b}.yao.moving i{box-shadow:0 0 10px #e7c87c}.yao em{font-style:normal;color:#f0cc72;font-size:11px}.result footer{text-align:center;margin-top:22px}.toast{position:fixed;bottom:28px;left:50%;transform:translateX(-50%);padding:10px 20px;border-radius:8px;background:#b54b62;color:#fff}@media(max-width:600px){.liuyao-card{padding:20px}.result-head,.hexagrams{gap:14px}.hexagrams{margin:20px 0}.hexagrams section{width:calc(50vw - 30px)}}
</style>